struct MainObject : Object {
  const char* ruby_class_name() const override { return "MainObject"; }

  virtual BasicObject* m_run_benchmark(Array* args, Hash* kwargs = nullptr, Proc* block = nullptr) {
    BasicObject* __anon_rest__ = args;  // *rest = whole args
    Proc* _block = block;
    Proc* __anon_block__ = block;
    return nil_instance();
    return nil_instance();
  }

  virtual BasicObject* m_collect(Array* args, Hash* kwargs = nullptr, Proc* block = nullptr) {
    BasicObject* items = args;  // *rest = whole args
    Proc* _block = block;
    return items->m_size((new Array({})), nullptr, nullptr);
    return nil_instance();
  }

  virtual BasicObject* m_first_of(Array* args, Hash* kwargs = nullptr, Proc* block = nullptr) {
    BasicObject* items = args;  // *rest = whole args
    Proc* _block = block;
    return items->m_aref((new Array({(&_f_i_0)})), nullptr, nullptr);
    return nil_instance();
  }

  void __top_level__() {
    BasicObject* arr = (new Array({(&_f_i_10), (&_f_i_20), (&_f_i_30), (&_f_i_40), (&_f_i_50)}));
    (ruby_puts(this->m_collect(static_cast<Array*>(arr), nullptr, nullptr)), nil_instance());
    (ruby_puts(this->m_first_of(static_cast<Array*>(arr), nullptr, nullptr)), nil_instance());
    BasicObject* arr2 = (new Array({(&_f_i_99), (&_f_i_100)}));
    (ruby_puts(this->m_collect(static_cast<Array*>(arr2), nullptr, nullptr)), nil_instance());
    (ruby_puts(this->m_first_of(static_cast<Array*>(arr2), nullptr, nullptr)), nil_instance());
  }
};

